/* Administration uses the authenticated server API; no service key is shipped here. */
const $=s=>document.querySelector(s),root=$('#root'),dialog=$('#editor');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>new Intl.NumberFormat('es-AR',{style:'currency',currency:'ARS',maximumFractionDigits:0}).format(Number(v)||0);
const date=v=>v?new Date(v).toLocaleString('es-AR'):'';
const photo=v=>/^https:\/\//.test(v||'')?v:/^\/?assets\/[\w.-]+$/.test(v||'')?'/'+v.replace(/^\//,''):'/assets/toyota-corolla-xei.webp';
const titles={overview:'Resumen',vehicles:'Vehículos',leads:'Consultas',tradeIns:'Tasaciones',financing:'Financiación',settings:'Configuración'};
let client,state=null,page='overview',images=[],query='',statusFilter='';
function notify(text){$('#notice').textContent=text;$('#notice').classList.add('show');clearTimeout(window.noticeTimer);window.noticeTimer=setTimeout(()=>$('#notice').classList.remove('show'),5000)}
async function api(path,method='GET',body){const {data:{session}}=await client.auth.getSession();if(!session)throw Error('Iniciá sesión para continuar.');const r=await fetch('/api/admin/'+path,{method,headers:{Authorization:'Bearer '+session.access_token,'Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{})});const data=await r.json();if(!r.ok)throw Error(data.error||'No se pudo guardar.');return data}
async function refresh(){state=await api('dashboard');render()}
function login(message='Ingresá con tu cuenta autorizada para gestionar el inventario.'){root.innerHTML=`<section class="login"><b class="brand">VZ <span>AUTOMOTORES</span></b><h1>Administración</h1><p>${esc(message)}</p><button id="google" class="primary">Continuar con Google</button><p id="authMessage" role="status"></p><a href="/">Volver al sitio</a></section>`;$('#google').onclick=async()=>{const button=$('#google');button.disabled=true;try{const {error}=await client.auth.signInWithOAuth({provider:'google',options:{redirectTo:location.origin+'/manage',queryParams:{prompt:'select_account'}}});if(error)throw error}catch(e){$('#authMessage').textContent='No se pudo iniciar sesión: '+e.message;button.disabled=false}}}
function render(){root.innerHTML=`<div class="layout"><aside><b class="brand">VZ <span>AUTOMOTORES</span></b><nav>${Object.entries(titles).map(([k,v])=>`<button data-nav="${k}" class="${page===k?'active':''}">${v}</button>`).join('')}</nav><p>${esc(state.user.email)}</p><button id="logout">Cerrar sesión</button><p><a href="/" target="_blank" rel="noopener">Ver sitio ↗</a></p></aside><section class="content"><header><div><small>VZ AUTOMOTORES / ADMINISTRACIÓN</small><h1>${titles[page]}</h1></div><button id="refresh">Actualizar</button></header><div id="view"></div></section></div>`;document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{page=b.dataset.nav;query='';statusFilter='';render()});$('#logout').onclick=async()=>{try{const {error}=await client.auth.signOut();if(error)throw error;state=null;dialog.close();login()}catch(e){notify(e.message)}};$('#refresh').onclick=()=>refresh().catch(e=>notify(e.message));renderPage()}
function renderPage(){const view=$('#view');if(page==='overview'){const v=state.vehicles;view.innerHTML=`<div class="stats">${[['Vehículos publicados',v.filter(x=>x.published).length],['Consultas nuevas',state.leads.filter(x=>x.status==='Nueva').length],['Tasaciones pendientes',state.tradeIns.filter(x=>x.status==='Pendiente').length],['Solicitudes de financiación',state.financing.length]].map(([label,n])=>`<div class="panel"><small>${label}</small><strong>${n}</strong></div>`).join('')}</div><div class="panel"><h2>Actividad reciente</h2>${state.events.length?state.events.slice(0,15).map(e=>`<p>${esc(({vehicle_created:'Vehículo creado',vehicle_updated:'Vehículo actualizado',vehicle_deleted:'Vehículo eliminado'})[e.event_type]||e.event_type)} · ${date(e.created_at)}</p>`).join(''):'<p>Todavía no hay actividad registrada.</p>'}</div>`;return}if(page==='settings'){settingsForm();return}if(page==='vehicles'){view.innerHTML=`<div class="toolbar"><input id="search" placeholder="Buscar marca, modelo o año" aria-label="Buscar vehículos" value="${esc(query)}"><select id="filter" aria-label="Estado"><option value="">Todos los estados</option>${['Disponible','Reservado','Vendido','Próximo ingreso'].map(s=>`<option ${statusFilter===s?'selected':''}>${s}</option>`).join('')}</select><button class="primary" id="new">Nuevo vehículo</button></div><div class="panel table-wrap"><table><thead><tr><th>Vehículo</th><th>Precio</th><th>Estado</th><th>Publicación</th><th>Acciones</th></tr></thead><tbody id="rows"></tbody></table></div>`;$('#new').onclick=()=>vehicleForm();$('#search').oninput=e=>{query=e.target.value;vehicleRows()};$('#filter').onchange=e=>{statusFilter=e.target.value;vehicleRows()};vehicleRows();return}recordsView()}
function vehicleRows(){const list=state.vehicles.filter(v=>(!statusFilter||v.status===statusFilter)&&`${v.brand} ${v.model} ${v.year}`.toLowerCase().includes(query.toLowerCase()));$('#rows').innerHTML=list.map(v=>`<tr><td><div class="row"><img src="${esc(photo(v.images?.[0]))}" alt="${esc(v.model)}"><div><b>${esc(v.brand)} ${esc(v.model)}</b><small>${v.year} · ${Number(v.kilometers).toLocaleString('es-AR')} km</small></div></div></td><td>${money(v.price)}</td><td><span class="pill">${esc(v.status)}</span></td><td>${v.published?'Publicado':'Oculto'}${v.featured?' · Destacado':''}</td><td><div class="actions"><button data-edit="${v.id}">Editar</button><button class="danger" data-delete="${v.id}">Eliminar</button></div></td></tr>`).join('')||'<tr><td colspan="5" class="empty">No hay vehículos. Cargá el primero con “Nuevo vehículo”.</td></tr>';document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>vehicleForm(state.vehicles.find(v=>v.id===b.dataset.edit)));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=async()=>{const v=state.vehicles.find(v=>v.id===b.dataset.delete);if(!confirm(`¿Eliminar ${v.brand} ${v.model}? Esta acción no se puede deshacer.`))return;b.disabled=true;try{await api('vehicles','DELETE',{id:v.id});await refresh();notify('Vehículo eliminado.')}catch(e){b.disabled=false;notify(e.message)}})}
function field(name,label,value='',type='text',extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function select(name,label,options,value){return `<label>${label}<select name="${name}">${options.map(o=>`<option ${o===value?'selected':''}>${esc(o)}</option>`).join('')}</select></label>`}
function openEditor(html){$('#editorBody').innerHTML=html;dialog.showModal();dialog.querySelector('input,select,button')?.focus()}
dialog.querySelector('.close').onclick=()=>dialog.close();
function vehicleForm(v={}){images=[...(v.images||[])];openEditor(`<h2>${v.id?'Editar vehículo':'Nuevo vehículo'}</h2><form id="vehicleForm"><div class="fields">${field('brand','Marca',v.brand,'text','required maxlength="80"')}${field('model','Modelo',v.model,'text','required maxlength="100"')}${field('year','Año',v.year||new Date().getFullYear(),'number','required min="1950" max="2100"')}${field('kilometers','Kilómetros',v.kilometers||0,'number','required min="0" step="1"')}${field('price','Precio en pesos',v.price||0,'number','required min="0" step="1"')}${select('status','Estado',['Disponible','Reservado','Vendido','Próximo ingreso'],v.status||'Disponible')}${select('fuel','Combustible',['Nafta','Diésel','Híbrido','Eléctrico','GNC'],v.fuel)}${select('transmission','Transmisión',['Manual','Automático'],v.transmission)}${select('category','Tipo',['Auto','Sedán','Hatchback','SUV','Pickup','Utilitario'],v.category)}${field('color','Color',v.color)}${field('engine','Motor y potencia',v.engine)}<label class="wide">Descripción<textarea name="description" maxlength="3000">${esc(v.description)}</textarea></label><label class="wide">Equipamiento (uno por línea)<textarea name="equipment">${esc((v.equipment||[]).join('\n'))}</textarea></label><label><input name="published" type="checkbox" ${v.published!==false?'checked':''}> Publicado en el catálogo</label><label><input name="featured" type="checkbox" ${v.featured?'checked':''}> Destacado</label><label class="wide">Fotos (JPG, PNG o WebP, hasta 3 MB por foto)<input id="photos" type="file" multiple accept="image/jpeg,image/png,image/webp"></label><div id="gallery" class="gallery wide"></div></div><p id="formError" role="alert"></p><div class="form-actions"><button type="button" id="cancel">Cancelar</button><button class="primary" id="saveVehicle">Guardar vehículo</button></div></form>`);$('#cancel').onclick=()=>dialog.close();gallery();$('#photos').onchange=async e=>{const save=$('#saveVehicle');save.disabled=true;try{for(const file of e.target.files){if(images.length>=20)throw Error('Máximo 20 fotos.');if(file.size>3*1024*1024)throw Error('Cada foto debe pesar menos de 3 MB.');if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Formato no admitido.');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)});const result=await api('upload','POST',{data,name:file.name});images.push(result.url);gallery()}$('#formError').textContent='Fotos cargadas. Guardá el vehículo para asociarlas.'}catch(err){$('#formError').textContent=err.message}finally{save.disabled=false;e.target.value=''}};$('#vehicleForm').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));for(const k of ['year','kilometers','price'])b[k]=Number(b[k]);b.published=e.target.elements.published.checked;b.featured=e.target.elements.featured.checked;b.equipment=b.equipment.split('\n').map(x=>x.trim()).filter(Boolean);b.images=images;b.id=v.id;$('#saveVehicle').disabled=true;try{await api('vehicles',v.id?'PUT':'POST',b);dialog.close();await refresh();notify('Vehículo guardado en la base de datos.')}catch(err){$('#formError').textContent=err.message;$('#saveVehicle').disabled=false}}}
function gallery(){$('#gallery').innerHTML=images.map((img,i)=>`<figure><img src="${esc(photo(img))}" alt="Foto ${i+1}"><figcaption>${i===0?'Portada':`Foto ${i+1}`}</figcaption><button type="button" data-remove="${i}">Quitar</button>${i?`<button type="button" data-cover="${i}">Portada</button>`:''}</figure>`).join('');document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{images.splice(Number(b.dataset.remove),1);gallery()});document.querySelectorAll('[data-cover]').forEach(b=>b.onclick=()=>{images.unshift(images.splice(Number(b.dataset.cover),1)[0]);gallery()})}
const recordConfig={leads:{table:'leads',states:['Nueva','Contactado','Visita agendada','Cerrada']},tradeIns:{table:'trade_ins',states:['Pendiente','Evaluación','Tasado','Aceptado','Rechazado']},financing:{table:'financing_requests',states:['Pendiente','Evaluación','Aprobada','Rechazada']}};
function recordsView(){$('#view').innerHTML=`<div class="panel table-wrap"><table><thead><tr><th>Cliente</th><th>Vehículo</th><th>Recibida</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${state[page].map(r=>`<tr><td>${esc(r.name||'Sin nombre')}<small>${esc(r.phone)}</small></td><td>${esc(r.vehicles?`${r.vehicles.brand} ${r.vehicles.model}`:r.brand?`${r.brand} ${r.model}`:'Consulta general')}</td><td>${date(r.created_at)}</td><td><span class="pill">${esc(r.status)}</span></td><td><button data-record="${r.id}">Ver y responder</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">Todavía no hay solicitudes recibidas.</td></tr>'}</tbody></table></div>`;document.querySelectorAll('[data-record]').forEach(b=>b.onclick=()=>recordForm(state[page].find(r=>r.id===b.dataset.record)))}
function recordForm(r){const cfg=recordConfig[page],phone=String(r.phone||'').replace(/\D/g,''),wa=phone.startsWith('54')?phone:'549'+phone;openEditor(`<h2>${esc(r.name||'Solicitud')}</h2><p>${esc(r.phone)} · ${esc(r.email)}</p><p>${esc(r.message||r.notes||'')}</p>${page==='financing'?`<p>Valor: ${money(r.vehicle_value)} · Anticipo: ${money(r.deposit)} · ${r.installments} cuotas</p>`:''}${page==='tradeIns'?`<p>${esc(r.brand)} ${esc(r.model)} · ${r.year} · ${r.kilometers} km</p><div class="gallery">${(r.images||[]).map(x=>`<a href="${esc(photo(x))}" target="_blank" rel="noopener"><img src="${esc(photo(x))}" alt="Usado ofrecido"></a>`).join('')}</div>`:''}<form id="recordForm">${select('status','Estado de la solicitud',cfg.states,r.status)}<div class="form-actions">${phone?`<a class="button" href="https://wa.me/${wa}" target="_blank" rel="noopener">Responder por WhatsApp</a>`:''}<button class="primary">Guardar estado</button></div><p role="alert" id="recordError"></p></form>`);$('#recordForm').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;try{await api('records','PATCH',{table:cfg.table,id:r.id,status:e.target.elements.status.value});dialog.close();await refresh();notify('Estado actualizado.')}catch(err){$('#recordError').textContent=err.message;button.disabled=false}}}
function settingsForm(){const s=state.settings;$('#view').innerHTML=`<form id="settingsForm" class="panel"><h2>Información de la concesionaria</h2><div class="fields">${field('business_name','Nombre comercial',s.business_name,'text','required')}${field('city','Localidad',s.city,'text','required')}${field('address','Dirección',s.address)}${field('phone','Teléfono',s.phone,'tel','required')}${field('whatsapp','WhatsApp con código de país',s.whatsapp,'text','required pattern="[0-9]{8,16}"')}${field('email','Email',s.email,'email')}${field('hours','Horarios',s.hours)}${field('instagram','Instagram',s.instagram)}<label><input type="checkbox" name="show_prices" ${s.show_prices?'checked':''}> Mostrar precios</label><label><input type="checkbox" name="show_sold" ${s.show_sold?'checked':''}> Mostrar vehículos vendidos</label></div><div class="form-actions"><button class="primary">Guardar configuración</button></div><p id="settingsError" role="alert"></p></form>`;$('#settingsForm').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.target));b.show_prices=e.target.elements.show_prices.checked;b.show_sold=e.target.elements.show_sold.checked;const button=e.target.querySelector('button');button.disabled=true;try{await api('settings','PUT',b);await refresh();notify('Configuración guardada.')}catch(err){$('#settingsError').textContent=err.message;button.disabled=false}}}
(async()=>{try{const response=await fetch('/api/config');if(!response.ok)throw Error('La conexión no está disponible.');const config=await response.json();client=window.supabase.createClient(config.url,config.anonKey,{auth:{flowType:'pkce',detectSessionInUrl:true,persistSession:true}});const {data:{session},error}=await client.auth.getSession();if(error)throw error;if(session){try{await refresh()}catch(e){login(e.message)}}else login();client.auth.onAuthStateChange(event=>{if(event==='SIGNED_OUT'){state=null;dialog.close();login()}})}catch(e){root.innerHTML=`<section class="login"><h1>No pudimos abrir el panel</h1><p>${esc(e.message)}</p><button onclick="location.reload()">Reintentar</button></section>`}})();
